import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { submitApplicationHandler } from "../handlers/submitApplicationHandler";
import type { ApiError } from "../runtime/client";
import type { SubmitApplicationRequest } from "../types/SubmitApplicationRequest";
import type { TeamPartition } from "../types/TeamPartition";

type Data = Awaited<ReturnType<typeof submitApplicationHandler>>;
type Vars = { teamPk: TeamPartition; body: SubmitApplicationRequest };

export function useSubmitApplication(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => submitApplicationHandler(vars.teamPk, vars.body),
    ...options,
  });
}
